recs.append(R(9602951,"چیا انڈے کا متبادل (یا فلیکس انڈا بھی!)",
"چیا انڈے کا متبادل (یا فلیکس انڈا) سادہ اور ہمہ گیر ہے۔ سیکھیں کہ اس متبادل کو اپنی تمام پسندیدہ بیکنگ کی ترکیبوں میں کیسے استعمال کریں!",
"1","1 انڈا",
["1 کھانے کا چمچ چیا کے بیج یا پسے ہوئے السی کے بیج","3 کھانے کے چمچ پانی"],
["ایک چھوٹے پیالے میں چیا یا السی کو پانی کے ساتھ ملائیں۔ 5 منٹ (یا زیادہ دیر) رکھا رہنے دیں اور اپنی پسندیدہ ترکیبوں میں استعمال کریں۔"],
["اس چیا انڈے کی ترکیب کے لیے آپ کو اپنے بیج پیسنے کی ضرورت نہیں۔ تاہم اگر آپ زیادہ نخرے والے کھانے والوں سے بیجوں کی بناوٹ چھپانا چاہتے ہیں تو ضرور پیس لیں۔ یا اگر آپ انہیں تیار شدہ چیز میں نہیں دیکھنا چاہتے تو کالے کی جگہ سفید بیج استعمال کریں۔ اگرچہ آپ زیادہ تر بیکنگ کی ترکیبوں میں فلیکس انڈا اور چیا انڈا ایک دوسرے کی جگہ استعمال کر سکتے ہیں، مجھے اس کے غیر جانبدار ذائقے کی وجہ سے چیا پسند ہے۔ اس کے باوجود، میرے پاس الماری میں جو بھی ہو میں وہی استعمال کرتی ہوں، تو آپ کے پاس جو ہو وہی استعمال کریں!"],[]))
recs.append(R(9604269,"ویگن اخروٹ پنیر ساس [بغیر تیل]",
"ویگن اخروٹ پنیر ساس ذائقے سے بھرپور ہے، صرف 5 اجزاء درکار ہیں اور محض پانچ منٹ میں تیار ہو جاتی ہے! پکانے یا کاٹنے کی ضرورت نہیں۔",
"6 سرونگ","1 سرونگ",
["1 ¼ کپ اخروٹ","2 کھانے کے چمچ نیوٹریشنل ییسٹ","½ چائے کا چمچ پیاز پاؤڈر","½ چائے کا چمچ سمندری نمک","¾ کپ گرم پانی، اور مطلوبہ گاڑھے پن کے لیے اختیاری ایک دو کھانے کے چمچ مزید"],
["کیتلی یا چھوٹے برتن میں ایک دو کپ تازہ پانی ابالیں۔ (کیونکہ کچھ بخارات بن کر اڑ جائے گا۔)",
"گرم پانی کے صرف 3/4 کپ کے ساتھ تمام اجزاء بلینڈر میں ڈالیں اور ہموار اور کریمی ہونے تک پروسیس کریں۔ اخروٹ کو مکمل ٹوٹ کر ہموار ہونے میں تقریباً ایک منٹ لگے گا۔ ضرورت ہو تو اپنا بلینڈر بند کریں اور مطلوبہ بناوٹ آنے تک دوبارہ شروع کریں۔ مسالا چکھیں اور ضرورت ہو تو ٹھیک کر لیں۔ اگر آپ کو پتلی ساس پسند ہے تو 1-2 کھانے کے چمچ مزید پانی ڈالیں اور دوبارہ بلینڈ کریں۔"],
["اگر آپ کے پاس طاقتور بلینڈر ہے تو اخروٹ بھگونے کی ضرورت نہیں۔ اگر نہیں تو انہیں 30 منٹ گرم پانی میں بھگو کر بلینڈر میں ڈالنے سے پہلے چھان لیں۔ اگر آپ طاقتور بلینڈر استعمال نہیں کر رہے تو اسے بند کریں، 30 سیکنڈ انتظار کریں اور اخروٹ پنیر کے ہموار ہونے تک دوبارہ شروع کریں۔ (اس سے کم طاقتور بلینڈر کے زیادہ گرم ہونے سے بچاؤ ہوگا۔) اگر آپ پتلی ساس پسند کرتے ہیں تو مطلوبہ گاڑھا پن حاصل کرنے کے لیے ضرورت کے مطابق 1-2 کھانے کے چمچ اضافی گرم پانی ڈالیں۔ اسے بدل کر دیکھیں! اگر آپ ذائقے بدلنا چاہتے ہیں تو پیاز پاؤڈر کی جگہ لہسن پاؤڈر، پاپریکا، سموکڈ پاپریکا یا کوئی بھی دوسرا مسالا استعمال کریں۔ (یاد رکھیں کہ گہرے مسالے آپ کے اخروٹ پنیر ساس کا رنگ بدل دیں گے۔) بچی ہوئی ساس بند ڈبے میں فریج میں 3 دن تک رہتی ہے۔ پیش کرنے سے پہلے دوبارہ گرم کریں۔"],[]))
